'use strict';
const $=id=>document.getElementById(id);let provider='auth0',journey='live',stage=0,timer=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function stages(){const normal=[{label:'Configure',title:'01 / Set the assessment context',text:'The operator supplies the tenant or org, environment and an existing API token to the local CLI. No sign-in traffic passes through Pulse.',nodes:['collect'],edge:null},{label:'Request',title:'02 / Request provider configuration',text:`The ${provider==='auth0'?'Auth0 Management API receives HTTPS GET requests with a Bearer token':'Okta API receives HTTPS GET requests using OAuth Bearer or SSWS authentication'}. Collection is read-only.`,nodes:['collect',provider],edge:['collect',provider]},{label:'Collect',title:'03 / Return configuration and collection status',text:'API responses carry settings, applications, policies and other assessed resources. Each collector records success, skipped or failed status.',nodes:[provider,'collect'],edge:[provider,'collect']},{label:'Normalize',title:'04 / Assemble the normalized snapshot',text:'Provider-specific collectors form a snapshot in local memory. Saving a snapshot is optional; the CLI applies its current redaction behavior to live collection.',nodes:['collect','snapshot'],edge:['collect','snapshot']},{label:'Analyze',title:'05 / Turn observations into findings',text:'Deterministic rules attach evidence, severity, classification and confidence. Provider-specific scoring and recommendations create the structured report.',nodes:['snapshot','analyze'],edge:['snapshot','analyze']},{label:'Report',title:'06 / Render and review locally',text:'Write HTML, Markdown and JSON reports. Separate commands compare two reports or combine provider summaries; an engineer reviews the conclusions.',nodes:['analyze','report','compare','summary'],edge:['analyze','report']}];
if(journey==='offline'){normal[0]={label:'Select file',title:'01 / Select a local snapshot',text:'Use --from-snapshot to assess a previously saved snapshot. A provider token is not needed for this path.',nodes:['snapshot'],edge:null};normal[1]={label:'Load',title:'02 / Load local configuration',text:'The CLI reads a local JSON snapshot. No network requests are made in this assessment path.',nodes:['snapshot'],edge:null};normal[2]={label:'Coverage',title:'03 / Preserve the supplied collection context',text:'Collector status and missing scopes travel with the snapshot. Imported evidence is only as trustworthy and current as its source.',nodes:['snapshot'],edge:null};normal[3]={label:'Prepare',title:'04 / Pass the snapshot to the analyzer',text:'The same provider analyzer consumes the snapshot. The current import path has validation and sanitization gaps tracked in the backlog.',nodes:['snapshot'],edge:null};}
if(journey==='partial'){normal[2]={label:'403 denied',title:'03 / A permission gap becomes visible',text:'A collector receiving 403 is marked skipped. Auth0 reports required scopes; Okta distinguishes OAuth scopes from SSWS/admin permissions. The assessment continues with a gap.',nodes:[provider,'collect'],edge:[provider,'collect']};normal[5].text='The report carries partial coverage and collector gaps. A good numeric score cannot establish that uncollected controls are safe.';}
if(journey==='retry')normal[2]={label:'429 retry',title:'03 / Back off after rate limiting',text:'The client uses rate-limit headers or backoff and retries within its configured limit. This illustrated path succeeds on retry; exhaustion is reported as a failed collector.',nodes:[provider,'collect'],edge:[provider,'collect']};
if(journey==='unauthorized')return normal.slice(0,2).concat({label:'401 stop',title:'03 / Stop on an invalid credential',text:'The HTTP client raises AuthenticationError. The scan stops so the operator can correct the credential; no completed assessment is produced.',nodes:[provider,'collect'],edge:[provider,'collect']});return normal;}
function draw(){const list=stages(),s=list[stage];$('stage-strip').style.gridTemplateColumns=`repeat(${list.length===3?3:6},1fr)`;if(innerWidth<=800)$('stage-strip').style.gridTemplateColumns='repeat(3,1fr)';$('stage-strip').innerHTML=list.map((x,i)=>`<button type="button" data-stage="${i}" ${i===stage?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${x.label}</button>`).join('');$('stage-title').textContent=s.title;$('stage-description').textContent=s.text;$('flow-prev').disabled=stage===0;$('flow-next').disabled=stage===list.length-1;$('flow-status').textContent=stage===list.length-1&&!timer?(journey==='unauthorized'?'Stopped · 401':'Complete'):timer?'Playing':'Paused';$('flow-play').textContent=timer?'Ⅱ Pause':'▷ Play flow';$('flow-diagram').classList.toggle('paused',!timer);document.querySelectorAll('.diagram-node,.engine-node').forEach(n=>n.classList.toggle('selected',s.nodes.includes(n.id.replace('node-',''))));document.querySelectorAll('[data-provider]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.provider===provider)));$('collector-status').textContent=journey==='offline'?'Bypassed · local snapshot':journey==='partial'&&stage>=2?'Partial collection · 403':journey==='unauthorized'&&stage>=2?'Authentication failed · stop':journey==='retry'&&stage===2?'Rate limited · retrying':'GET operations only';$('provider-note').textContent=journey==='offline'?'Provider API is bypassed. This flow runs entirely from a local snapshot.':'Configuration is requested over HTTPS using an externally supplied token.';drawWires();}
function point(id,side){const a=$('node-'+id).getBoundingClientRect(),b=$('flow-diagram').getBoundingClientRect();return {x:a.left-b.left+(side==='left'?0:side==='right'?a.width:a.width/2),y:a.top-b.top+(side==='top'?0:side==='bottom'?a.height:a.height/2)};}
function path(a,b){const vertical=['collect','snapshot'].includes(a)&&['snapshot','analyze'].includes(b),pa=point(a,vertical?'bottom':a===provider?'right':b===provider?'left':'right'),pb=point(b,vertical?'top':b===provider?'right':a===provider?'left':'left');return vertical?`M${pa.x},${pa.y} L${pb.x},${pb.y}`:`M${pa.x},${pa.y} C${(pa.x+pb.x)/2},${pa.y} ${(pa.x+pb.x)/2},${pb.y} ${pb.x},${pb.y}`;}
function drawWires(){if(innerWidth<=800){$('wire-paths').innerHTML='';return;}const active=stages()[stage].edge,edges=journey==='offline'?[['snapshot','analyze'],['analyze','report'],['analyze','compare'],['analyze','summary']]:[[provider,'collect'],['collect','snapshot'],['snapshot','analyze'],['analyze','report'],['analyze','compare'],['analyze','summary']];let html=edges.map(e=>`<path class="wire" d="${path(...e)}" marker-end="url(#arrow)"/>`).join('');if(active){const d=path(...active);html+=`<path class="wire active-wire" d="${d}" marker-end="url(#arrow)"/>`;if(!reduced)html+=`<circle class="packet" r="5" style="offset-path:path('${d}')"/>`;} $('wire-paths').innerHTML=html;}
function stop(){clearInterval(timer);timer=null;}function play(){if(stage===stages().length-1)stage=0;timer=setInterval(()=>{stage++;if(stage===stages().length-1)stop();draw();},2800);draw();}$('flow-play').onclick=()=>{if(timer){stop();draw();}else play();};$('flow-replay').onclick=()=>{stop();stage=0;play();};$('flow-prev').onclick=()=>{stop();stage=Math.max(0,stage-1);draw();};$('flow-next').onclick=()=>{stop();stage=Math.min(stages().length-1,stage+1);draw();};$('journey').onchange=e=>{stop();journey=e.target.value;stage=0;draw();};document.addEventListener('click',e=>{const p=e.target.closest('[data-provider]'),s=e.target.closest('[data-stage]');if(p){stop();provider=p.dataset.provider;stage=0;draw();}if(s){stop();stage=Number(s.dataset.stage);draw();}});new ResizeObserver(drawWires).observe($('flow-diagram'));window.addEventListener('resize',draw);draw();
